#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <iomanip>

struct Account {
    int id;
    std::string name;
    double balance;
};

struct Transaction {
    int id;
    double amount;
};

int main() {
    // Simulated sequential files (pre-sorted by id)
    std::vector<Account> master = {
        {100, "Alan Jones", 348.17},
        {300, "Mary Smith", 27.19},
        {500, "Sam Sharp", 0.00},
        {700, "Suzy Green", -14.22}
    };

    std::vector<Transaction> trans = {
        {100, 27.14},
        {300, 62.11},
        {300, 83.89}, // Duplicate key
        {400, 100.56},// Unmatched
        {700, 80.78},
        {700, 1.53},
        {900, 82.17}  // Unmatched
    };

    size_t mIdx = 0, tIdx = 0;
    std::vector<Account> newMaster;

    std::cout << std::fixed << std::setprecision(2);

    while (mIdx < master.size() && tIdx < trans.size()) {
        if (master[mIdx].id == trans[tIdx].id) {
            master[mIdx].balance += trans[tIdx].amount;
            ++tIdx; // Consume transaction, keep master to allow duplicate keys
        } else if (master[mIdx].id < trans[tIdx].id) {
            newMaster.push_back(master[mIdx]);
            ++mIdx;
        } else {
            std::cout << "Unmatched transaction record for account number " << trans[tIdx].id << "\n";
            ++tIdx;
        }
    }

    // Flush remaining master records
    while (mIdx < master.size()) {
        newMaster.push_back(master[mIdx++]);
    }

    // Check remaining unmatched transactions
    while (tIdx < trans.size()) {
        std::cout << "Unmatched transaction record for account number " << trans[tIdx++].id << "\n";
    }

    std::cout << "\n--- Updated Master File ---\n";
    for (const auto& acc : newMaster) {
        std::cout << acc.id << " " << acc.name << " " << acc.balance << "\n";
    }

    return 0;
}

#include <iostream>
#include <sstream>
#include <cstring>
#include <iomanip>

// TriviallyCopyable fixed-size struct suitable for binary read/write
struct ToolRecord {
    int recordNumber; // 0 indicates empty slot
    char toolName[30];
    int quantity;
    double cost;
};

int main() {
    // Simulate random-access file in memory via std::stringstream in binary mode
    std::stringstream file(std::ios::in | std::ios::out | std::ios::binary);

    // 1. Initialize file with 10 empty records (scaled for demonstration)
    ToolRecord blank{0, "", 0, 0.0};
    for (int i = 0; i < 10; ++i) {
        file.write(reinterpret_cast<const char*>(&blank), sizeof(ToolRecord));
    }

    // 2. Insert records (Record #3: Electric sander, Record #7: Sledge hammer)
    auto insertTool = [&](int recNo, const char* name, int qty, double cost) {
        ToolRecord tool;
        tool.recordNumber = recNo;
        std::strncpy(tool.toolName, name, sizeof(tool.toolName) - 1);
        tool.toolName[sizeof(tool.toolName) - 1] = '\0';
        tool.quantity = qty;
        tool.cost = cost;

        std::streampos pos = static_cast<std::streamoff>((recNo - 1) * sizeof(ToolRecord));
        file.seekp(pos);
        file.write(reinterpret_cast<const char*>(&tool), sizeof(ToolRecord));
    };

    insertTool(3, "Electric sander", 7, 57.98);
    insertTool(7, "Sledge hammer", 11, 21.50);

    // 3. Update Record #3 (change quantity to 10)
    std::streampos pos3 = static_cast<std::streamoff>((3 - 1) * sizeof(ToolRecord));
    file.seekg(pos3);
    ToolRecord toolToUpdate;
    file.read(reinterpret_cast<char*>(&toolToUpdate), sizeof(ToolRecord));
    if (toolToUpdate.recordNumber != 0) {
        toolToUpdate.quantity = 10; // modified
        file.seekp(pos3);
        file.write(reinterpret_cast<const char*>(&toolToUpdate), sizeof(ToolRecord));
    }

    // 4. Read and display all existing records
    std::cout << std::left << std::setw(8) << "Record#" 
              << std::setw(20) << "Tool Name" 
              << std::setw(10) << "Quantity" 
              << std::setw(10) << "Cost" << "\n";
    std::cout << std::string(48, '-') << "\n";

    file.seekg(0);
    ToolRecord cur;
    while (file.read(reinterpret_cast<char*>(&cur), sizeof(ToolRecord))) {
        if (cur.recordNumber != 0) {
            std::cout << std::left << std::setw(8) << cur.recordNumber
                      << std::setw(20) << cur.toolName
                      << std::setw(10) << cur.quantity
                      << std::fixed << std::setprecision(2) << cur.cost << "\n";
        }
    }

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <iomanip>

struct PhishingTerm {
    std::string term;
    int points;
};

std::string toLower(std::string s) {
    for (char &c : s) {
        c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    }
    return s;
}

int main() {
    // Sample phishing rule set (weighted dictionary)
    std::vector<PhishingTerm> dictionary = {
        {"verify account", 3},
        {"urgent action", 2},
        {"password", 3},
        {"bank", 1},
        {"suspended", 2},
        {"social security", 3}
    };

    // Sample incoming email message body
    std::string emailBody = 
        "Dear customer, your bank account has been suspended! "
        "Urgent action required: please verify account credentials and enter your password.";

    std::string lowerBody = toLower(emailBody);
    int totalScore = 0;

    std::cout << std::left << std::setw(22) << "Phrase" 
              << std::setw(14) << "Occurrences" 
              << std::setw(12) << "Subtotal" << "\n";
    std::cout << std::string(48, '-') << "\n";

    for (const auto& item : dictionary) {
        std::string lowerTerm = toLower(item.term);
        int count = 0;
        size_t pos = lowerBody.find(lowerTerm, 0);
        while (pos != std::string::npos) {
            ++count;
            pos = lowerBody.find(lowerTerm, pos + lowerTerm.length());
        }

        if (count > 0) {
            int subtotal = count * item.points;
            totalScore += subtotal;
            std::cout << std::left << std::setw(22) << item.term
                      << std::setw(14) << count
                      << std::setw(12) << subtotal << "\n";
        }
    }

    std::cout << std::string(48, '-') << "\n";
    std::cout << "Total Risk Point Score: " << totalScore << "\n";

    if (totalScore >= 7) {
        std::cout << "Assessment: HIGH PROBABILITY of Phishing!\n";
    } else {
        std::cout << "Assessment: Low risk message.\n";
    }

    return 0;
}
